-- ── 2. profiles.name_sound: the search-only sound key, kept by the name trigger like name_key (a browser write cannot set it) ──
alter table public.profiles add column if not exists name_sound text;
grant select (name_sound) on table public.profiles to anon, authenticated;                       -- like name_key (0038): read to search
create or replace function public.profiles_clean_name() returns trigger language plpgsql set search_path = public as $$
declare n text; p text;
begin
  if tg_op = 'UPDATE' and new.name is not distinct from old.name then
    if old.name_key is not null and new.name_key is not distinct from old.name_key and old.name_sound is not null then
      new.name_key := old.name_key; new.name_needs_fix := old.name_needs_fix; new.name_sound := old.name_sound; return new;
    end if;
    new.name_key := public.person_name_key(new.name);
    new.name_sound := public.person_name_sound(new.name);
    new.name_needs_fix := public.person_name_problem(public.person_name_norm(new.name)) <> '';
    return new;
  end if;
  n := coalesce(nullif(public.person_name_norm(new.name), ''), 'Member');
  p := public.person_name_problem(n);
  if p <> '' and not public.is_server_call() then
    raise exception '%', public.person_name_message(new.name, p) using errcode = '23514', hint = 'name:' || p;
  end if;
  new.name := left(n, 200); new.name_needs_fix := p <> ''; new.name_key := public.person_name_key(new.name);
  new.name_sound := public.person_name_sound(new.name);
  return new;
end $$;
revoke all on function public.profiles_clean_name() from public, anon, authenticated, service_role;
drop trigger if exists trg_profiles_clean_name on public.profiles;
create trigger trg_profiles_clean_name before insert or update on public.profiles
  for each row execute function public.profiles_clean_name();
-- the ✎ picker searches by substring of the skeleton and of the sound key, oldest member first (S-03 fix 9): trigram indexes, as the
-- company directory has (0001); created_at orders the members of one skeleton
create index if not exists idx_profiles_name_key_trgm on public.profiles using gin (name_key gin_trgm_ops);
create index if not exists idx_profiles_name_sound_trgm on public.profiles using gin (name_sound gin_trgm_ops);
create index if not exists idx_profiles_name_trgm on public.profiles using gin (name gin_trgm_ops);
create index if not exists idx_profiles_name_key_created on public.profiles (name_key, created_at, id);

-- open_candidates() "returns setof profiles": its column list follows the table, now with name_sound (phone stays private — 0036)
do $do$
declare cols text;
begin
  select string_agg(case when column_name = 'phone' then 'null::text' else 'p.' || quote_ident(column_name) end, ', ' order by ordinal_position) into cols
    from information_schema.columns where table_schema = 'public' and table_name = 'profiles';
  execute format($f$create or replace function public.open_candidates(p_limit int default 40)
returns setof public.profiles language sql stable set search_path = public as $q$
  select %s
    from public.profiles p where p.open_to_work and p.id <> coalesce(auth.uid(), '00000000-0000-0000-0000-000000000000'::uuid)
     and p.id <> all (coalesce((select private.blocked_parties()), '{}'::uuid[]))
   order by p.created_at desc limit least(greatest(coalesce(p_limit, 40), 1), 100)
$q$$f$, cols);
end $do$;
revoke all on function public.open_candidates(int) from public, anon, authenticated, service_role;
grant execute on function public.open_candidates(int) to authenticated, service_role;

-- ── 3. existing names: never renamed; flagged when the new rule refuses them; keyed again and given their sound key ──
do $$
declare total int; differ int; dash1 int; unflag int; rekeyed int; renamed int; flagged_before int; flagged_after int;
begin
  create temp table names9_before on commit drop as select id, name, name_key, name_needs_fix from public.profiles;
  select count(*), count(*) filter (where name_needs_fix) into total, flagged_before from public.profiles;
  select count(*) into differ from public.profiles where name is distinct from public.person_name_norm(name);
  select count(*) into dash1 from public.profiles
   where not name_needs_fix and strpos(name, ' - ') = 0 and (name ~ '[^ -]- [^ -]' or name ~ '[^ -] -[^ -]') and public.person_name_problem(public.person_name_norm(name)) = 'dash';
  select count(*) into unflag from public.profiles where name_needs_fix and public.person_name_problem(public.person_name_norm(name)) = '';
  update public.profiles set name_key = null
   where name_key is distinct from public.person_name_key(name)
      or name_sound is distinct from public.person_name_sound(name)
      or name_needs_fix is distinct from (public.person_name_problem(public.person_name_norm(name)) <> '');
  get diagnostics rekeyed = row_count;
  select count(*) into renamed from public.profiles p join names9_before b on b.id = p.id where p.name is distinct from b.name;
  select count(*) filter (where name_needs_fix) into flagged_after from public.profiles;
  raise notice 'names (0039_names_rule_9): % profiles, % renamed, % stored names the rule would now write differently (kept as stored), % newly flagged for a one-sided hyphen, % unflagged (allowed now: the look-alike-only refusals are gone), % rekeyed, flagged % → %',
    total, renamed, differ, dash1, unflag, rekeyed, flagged_before, flagged_after;
end $$;

notify pgrst, 'reload schema';
